// runs once at flow start
var zones = ['workshop','livingroom','bedroom','nursery','drawing_room']
flow.set('zones', zones)
flow.set('thermostats', {})
flow.set('sensor_state', {})   // {zone:{lastVal,lastChangeTs,ageMs,stuck}}
flow.set('effective', {})      // {zone: temperature actually used}
flow.set('trv_state', {})      // {zone:{integral,lastSent,lastTs}}

// ---- tunables -------------------------------------------------------
flow.set('thermostat_off_temp', 16)      // target substituted when the zone's mode is off
flow.set('off_lead_margin',    1.0)      // K above thermostat_off_temp; an OFF zone warmer
                                         // than this cannot lead. Frost floor still applies below it.
// TRV control: per-zone PI on the ROOM sensor, output is the commanded setpoint.
// Uniform across all five zones (Danfoss LC-13, Eurotronic Spirit, Sonoff TRVZB),
// so there are no per-model code paths. Each TRV keeps its own internal loop; the
// integral absorbs its slowly varying sensor bias.
flow.set('trv_off_temp',        16)      // commanded when the zone's mode is off
flow.set('trv_kp',             2.0)      // K of setpoint offset per K of room error
flow.set('trv_ti_s',          1800)      // integral time, s. Bias of ~2.4 K absorbed in ~1 h at 1 K error
flow.set('trv_integral_clamp',   7)      // K, upper bound on the bias correction. Raised 5 -> 7 on
                                         // 2026-11-20: the TRV head reads high when its own radiator is
                                         // hot (18.8 -> 21.8 overnight while the room moved 18.2 -> 19.2),
                                         // so the valve throttles itself while the room is still short.
                                         // Measured 14 days: only bedroom (5.2% of samples) and livingroom
                                         // (3.1%) ever reach the clamp; the other three never exceed 4.0.
                                         // cmd_raw peaked at 27.9, so +2 stays inside the 30 ceiling.
// Asymmetric lower bound. The integral's real job is absorbing the TRV's POSITIVE
// sensor bias (valve reads warm), so it needs room to go up, not down. A large
// negative integral only cancels the proportional term and holds the valve shut
// against a genuine deficit. Measured 3 Nov: drawing_room sat 0.4-0.7 K ABOVE target
// for 8 h with mode=heat, wound the integral to -1.05, then could not open when the
// morning target rose: 20.0 + 2*0.3 - 1.05 = 19.55, at or below the room itself.
flow.set('trv_integral_min',      0)      // K. Zero, not negative: a TRV command below the
// zone's target cannot open the valve, so negative integral is dead range. Measured 5 Nov:
// drawing_room sat at -0.413 with the proportional term zeroed by the deadband, giving a command
// of 19.09 against a 19.5 target, and the room held 0.1-0.2 K short all night. Same reasoning
// as the heating-only argument for the boiler PID: we have no cooling actuator.
flow.set('trv_off_decay_s',   7200)      // s. Integral decay time constant while a zone is off; 2 h.
flow.set('trv_deadband_k',     0.2)      // room error below this counts as zero
flow.set('trv_write_step',     1.0)      // only write when the command moves this much
flow.set('trv_min_setpoint',    16)
flow.set('trv_max_setpoint',    30)

flow.set('stuck_ms',  12*60*60*1000)     // BACKSTOP only: no reading change for 12 h.
// Measured over 30 days: healthy sensors hold an identical value for up to 7.7 h
// (nursery, overnight), so a 3 h threshold produced 19 false positives.
// PRIMARY detection is current_temperature null/unavailable, which is immediate,
// but that needs expire_after on the tasmota_ble mqtt sensors in HA.

// OpenTherm control setpoint: 10 = "no heat needed", 0 = "I do not control"
// (hardware backup takes over; 0 is sent only by the surrender path).
// The bottom of the PID range must stay 10, never a real demand value.
// Integral-step correction, see 'Select leader and feed to PID'.
flow.set('pid_step_thresh',   0.8)      // K. Below this, config changes are small edits; above, mode flips.
flow.set('pid_rise_k',          2)      // K. External heat source: rise over the window below.
flow.set('pid_rise_window_s', 1800)     // 30 min. Heating alone never exceeded 1.0 K/30 min in 21 days.
flow.set('pid_temp_hist',      {})      // {zone: [[ts,temp],...]} rolling, for the rise test
flow.set('pid_rise_latch',   null)      // zone currently counted as an external-heat episode
flow.set('pid_prev_leader', null)      // gate: only the DEPARTING leader's own config change counts
flow.set('pid_pb',              6)      // must match the PID node's proportional band
flow.set('pid_prev_err',     null)
flow.set('pid_last_integral',null)

flow.set('flow_idle',           10)      // PID exactly 0 -> 10 C = no heat needed
flow.set('flow_min',            20)      // any positive output starts here: radiators
                                         // below 20 C transfer almost nothing, and idle
                                         // water sits at 25 C median, so a command under
                                         // 20 can never produce heat
flow.set('flow_span',           55)      // PID 1.0 -> 75 C, still the ceiling
flow.set('flow_exp',           1.3)      // cmd = min + span*raw^k. k>1 bends the middle down:
                                         // zero-error point 47.5 -> 42.3 C, ceiling unchanged.
                                         // Was 1.4 (40.8 C) 16-20 Nov. Lowered after measuring a
                                         // 0.8 K overnight deficit commanding only 34.6 C, where the
                                         // old linear map gave 41.4. Recovery ran at 0.2 K/h.

