var zone = msg.payload
var e    = msg.data
var now  = Date.now()

var th = flow.get('thermostats') || {}
var ss = flow.get('sensor_state') || {}
var stuck_ms = flow.get('stuck_ms')

th[zone] = e
flow.set('thermostats', th)

// ---- stuck-sensor detection -----------------------------------------
// TIER 1 (immediate, reliable): current_temperature is null/undefined.
//   Happens when the source sensor goes 'unavailable'. Requires expire_after
//   on the MQTT sensor in HA -- otherwise a silent BLE sensor holds its last
//   value forever and this tier never fires.
// TIER 2 (backstop, slow): reading unchanged for stuck_ms (12 h).
//   Deliberately long: healthy sensors were measured flat for up to 7.7 h.
// last_updated is recorded for observability only -- it freezes in lockstep
// with the value, so it is NOT a usable liveness signal for these entities.
var cur = e.attributes.current_temperature
var st  = ss[zone] || {}
if (typeof cur !== 'number' || !isFinite(cur)) {
    st.lastVal = null
    if (!st.lastChangeTs) st.lastChangeTs = now
} else if (st.lastVal === undefined || st.lastVal === null || cur !== st.lastVal) {
    st.lastVal = cur
    st.lastChangeTs = now
}
st.ageMs = now - (st.lastChangeTs || now)
st.stuck = (st.lastVal === null) || (st.ageMs >= stuck_ms)
st.haLastUpdated = e.last_updated || null
st.haAgeMs = e.last_updated ? (now - new Date(e.last_updated).getTime()) : null
ss[zone] = st
flow.set('sensor_state', ss)

// ---- effective temperatures -----------------------------------------
// a stuck zone inherits the mean of the healthy zones
var vals = []
Object.keys(th).forEach(function (z) {
    var s = ss[z], c = th[z].attributes.current_temperature
    if (s && !s.stuck && typeof c === 'number' && isFinite(c)) vals.push(c)
})
var avg = vals.length ? vals.reduce(function (a, b) { return a + b }, 0) / vals.length : null

var eff = {}
Object.keys(th).forEach(function (z) {
    var s = ss[z], c = th[z].attributes.current_temperature
    eff[z] = (s && s.stuck) ? avg : c
})
flow.set('effective', eff)

var nstuck = Object.keys(ss).filter(function (z) { return ss[z].stuck }).length
node.status({ fill: nstuck ? 'yellow' : 'green', shape: 'ring',
    text: zone + ' ' + cur + ' | stuck:' + nstuck + ' | avg:' + (avg === null ? '-' : avg.toFixed(1)) })
return msg;

// Per-zone PI on the ROOM sensor. Output is the TRV's commanded setpoint.
// The TRV runs its own internal loop on its own (biased) sensor; the integral here
// absorbs that bias. Writes are gated by trv_write_step so the command settles
// instead of chattering, which is what the previous 5x-amplified version did.
var zone = msg.payload
var e    = msg.data
var trv  = 'climate.trv_' + zone
var now  = Date.now()

var eff = flow.get('effective') || {}
var ts  = flow.get('trv_state') || {}

var off_t  = flow.get('trv_off_temp')
var kp     = flow.get('trv_kp')
var ti_s   = flow.get('trv_ti_s')
var iclamp = flow.get('trv_integral_clamp')
var imin   = flow.get('trv_integral_min')
var dead   = flow.get('trv_deadband_k')
var step   = flow.get('trv_write_step')
var lo     = flow.get('trv_min_setpoint')
var hi     = flow.get('trv_max_setpoint')

var st = ts[zone] || { integral: 0, lastSent: null, lastTs: now }
if (st.integral < imin) st.integral = imin   // re-clamp state from before this limit existed
var dt = (now - (st.lastTs || now)) / 1000
st.lastTs = now

var target

// Key on MODE (data.state), not hvac_action. A generic_thermostat reports
// hvac_action 'off' transiently while its mode is being changed, and the old code
// latched the shut setpoint on that: measured 07 Oct, livingroom sat at 16 for
// 110 min with the room 1 K below target.
var tgtForHead = e.attributes.temperature
var errForHead = 0
var pTerm = 0

if (msg.data.state === 'off') {
    target = off_t
    // Decay rather than zero. A zone goes off for two very different reasons and
    // this node cannot tell them apart: a scheduled setback, or a presence dropout
    // where the radar loses a person who is in the room but still. Zeroing threw
    // away the whole accumulated bias on every short gap. Measured 15 Nov 20:46:
    // the bedroom radar went absent 38 min, an integral of 4.37 built over 90 min
    // was discarded, and the room then sat 0.3 K short until morning because the
    // command from a zero integral is barely above target.
    // Over 30 days bedroom had 34 off-periods under 2 h against a median of 228 min
    // and nursery 60 against a median of 95 min, so both populations are common.
    // tau = 2 h keeps 73% over 38 min, 14% over a 4 h setback, ~0 overnight.
    st.integral *= Math.exp(-dt / flow.get('trv_off_decay_s'))
} else {
    var tgt = e.attributes.temperature
    var cur = (eff[zone] !== undefined && eff[zone] !== null) ? eff[zone]
                                                             : e.attributes.current_temperature
    if (typeof tgt !== 'number' || typeof cur !== 'number' || !isFinite(tgt) || !isFinite(cur)) {
        ts[zone] = st; flow.set('trv_state', ts)
        node.status({ fill: 'yellow', shape: 'ring', text: zone + ' bad data, holding' })
        return [null, null, null]                          // hold the last command, do not thrash
    }
    var err = tgt - cur                      // positive means the room wants heat
    errForHead = err
    // soft deadband: subtract it rather than zeroing, so the proportional term stays
    // continuous. A hard deadband makes the command jump by kp*dead at the edge, and
    // every crossing then costs a write.
    if (err > dead) err = err - dead
    else if (err < -dead) err = err + dead
    else err = 0
    pTerm = kp * err

    // anti-windup: integrate only while the command is inside its limits
    var tentative = tgt + kp * err + st.integral
    if (dt > 0 && dt < 600 && tentative > lo && tentative < hi) {
        st.integral = st.integral + err * dt / ti_s
        if (st.integral > iclamp) st.integral = iclamp
        if (st.integral < imin)   st.integral = imin
    }
    target = tgt + kp * err + st.integral
}

// Headroom test (saturation condition). The question is whether a zone
// ever runs out of valve authority, which would mean the right response to a cold
// room is to open the valve rather than raise the whole house's water temperature.
// Measured over 7 days to 22 Oct: minimum headroom was 2-5 K, so saturation never
// occurred and the rule would have been inert. Export it and watch the cold week.
// Ceiling is the ACHIEVABLE max (tgt + kp*err + iclamp), not the configured clamp,
// because the integral clamp binds first.
var ceiling = Math.min(hi, tgtForHead + kp * Math.max(0, errForHead) + iclamp)
var headroom = ceiling - target
node.send([null, { payload: { op: 'set', val: headroom,
                              labels: { zone: zone, flag: 'cmd_headroom' } } }, null])

if (target < lo) target = lo
if (target > hi) target = hi
// Controller intent, exported every cycle before rounding and before the write dedupe,
// so it is visible even when no write happens. push = command - zone target.
var intent = { cmd_raw: target, p_term: pTerm, integral: st.integral }
if (typeof tgtForHead === 'number') intent.push = target - tgtForHead
Object.keys(intent).forEach(function (k) {
    node.send([null, { payload: { op: 'set', val: intent[k], labels: { zone: zone, flag: k } } }, null])
})
target = Math.round(target * 2) / 2          // TRVs take 0.5 C steps

// Compare against what the TRV ACTUALLY REPORTS, not what we last sent.
// st.lastSent alone is not self-correcting: measured 21 Oct, livingroom was
// written to 16 on its mode change, the device reverted to 18.5 six minutes
// later, and the dedupe then suppressed every rewrite for 9.9 h. Bedroom held
// 16.5 for 7.3 h the same way.
var actual = (msg.trv && msg.trv.attributes && typeof msg.trv.attributes.temperature === 'number')
             ? msg.trv.attributes.temperature : null

// Missing TRV state means the device did not report, so resend rather than suppress:
// an unreachable valve is exactly the one whose command most needs reasserting.
if (actual !== null && Math.abs(target - actual) < step) {
    ts[zone] = st; flow.set('trv_state', ts)
    node.status({ fill: 'grey', shape: 'ring',
        text: zone + ' ' + target.toFixed(1) + ' = dev ' + (actual === null ? '?' : actual)
              + ' (no write, I=' + st.integral.toFixed(2) + ')' })
    return [null, null, null]
}

st.lastSent = target
ts[zone] = st
flow.set('trv_state', ts)

msg.topic = trv
msg.data  = { entity_id: trv, temperature: target }
node.status({ fill: 'green', shape: 'dot',
    text: zone + ' -> ' + target.toFixed(1) + ' (I=' + st.integral.toFixed(2) + ')' })
node.log('TRV ' + trv + ' -> ' + target + ' (was ' + (actual === null ? 'unknown' : actual)
         + ', I=' + st.integral.toFixed(2) + ')')
// Every write, including a re-send of the same value after the device reverted.
// Writes go to a real counter (3rd output) so increase() survives restarts.
node.send([null, { payload: { op: 'set', val: target, labels: { zone: zone, flag: 'cmd_sent' } } }, null])
node.send([null, null, { payload: { op: 'inc', val: 1, labels: { zone: zone } } }])
return [msg, null, null];

var th  = flow.get('thermostats') || {}
var ss  = flow.get('sensor_state') || {}
var eff = flow.get('effective') || {}

var backup_temp = flow.get('thermostat_off_temp')

var zones = {}
Object.keys(th).forEach(function (z) { zones[z] = th[z] })
zones['backup'] = { entity_id: 'climate.backup', state: 'heat',
    attributes: { temperature: backup_temp, current_temperature: backup_temp + 3 } }

var max_demand = -100, leader = 'NOTSET', new_setpoint = backup_temp
var demands = {}, curs = {}

Object.keys(zones).forEach(function (zone) {
    var t   = zones[zone]
    var tgt = t.attributes.temperature
    if (t.state === 'off') tgt = backup_temp   // mode, not hvac_action (see TRV node)
    var cur = (zone === 'backup') ? t.attributes.current_temperature
            : ((eff[zone] !== undefined && eff[zone] !== null) ? eff[zone]
                                                              : t.attributes.current_temperature)
    // An OFF zone keeps its substituted 16 C target only as a FROST FLOOR. While it
    // is comfortably above that floor it must not lead: it would report a large
    // positive error (a room at 17.8 against 16 reports +1.8) which tells the PID the
    // house is too warm and winds the integral to the +pb/2 clamp. Measured over
    // 14 days: 2.2 h of off-zone leadership, every sample with proportional > +0.5,
    // median +1.80. Below floor+margin the zone stays eligible, so frost protection
    // is unchanged: at 15.5 C its demand is +0.5 and it still wins and still calls heat.
    if (zone !== 'backup' && t.state === 'off' &&
        typeof cur === 'number' && cur >= backup_temp + flow.get('off_lead_margin')) {
        return
    }
    if (typeof tgt !== 'number' || typeof cur !== 'number' || !isFinite(tgt) || !isFinite(cur)) {
        node.warn('skipping ' + zone + ': tgt=' + tgt + ' cur=' + cur)
        return
    }
    var demand = tgt - cur
    if (Math.abs(demand) > 15) {
        node.error('bad demand for ' + zone, msg)
        node.warn('bad demand ' + demand.toFixed(1) + ' for ' + zone + ' (tgt ' + tgt + ', cur ' + cur + ')')
        return
    }
    demands[zone] = demand
    curs[zone] = cur
    if (demand > max_demand) { leader = zone; max_demand = demand; new_setpoint = tgt }
})

if (leader === 'NOTSET') {
    node.error('no usable zone for leader selection', msg)
    node.status({ fill: 'red', shape: 'ring', text: 'no usable zone' })
    return null
}

var stuck = Object.keys(ss).filter(function (z) { return ss[z].stuck })
var out = {
    setpoint: new_setpoint,
    payload:  curs[leader],
    leader:   leader,
    demands:  demands,
    stuck:    stuck
}

// --- integral correction on a configuration change --------------------------
// The integral accumulates against the leader's error. When demand drops for a
// reason that is not the heating system's own doing, that history is stale and at
// ti=5000 s it takes hours to unwind, commanding heat into a satisfied house.
// Two kinds of event qualify, both treated the same way.
//
// 1. A scheduled or manual change to THE ZONE THAT WAS LEADING: a cron, a presence
//    flip, a target edit. Config is mode plus target, held per zone.
//    The gate is the PREVIOUS leader's own entry, not the house as a whole. When
//    the lead passes between two zones the error step is the gap between two
//    different rooms, and nothing physical changed; the correction must not fire
//    on that. Keying on any zone's config let it back in: on 8 Nov, 19:27 to
//    19:58, nursery (18.7/19.0) flickered into the lead for two cycles at a time
//    while bedroom (18.5/20.0) was the real leader, and presence flips elsewhere
//    opened the gate. Three corrections stacked the integral 0.28 -> 3.27 against
//    a clamp of 3.0 and cut the command 58 -> 33 C with the coldest room 1.5 K
//    short. Requiring the departing leader's own entry to have changed keeps every
//    legitimate case (bedroom goes off, the lead passes to nursery, the house
//    genuinely needs less heat) and rejects the swap.
//    Step threshold 0.8 K, from 7 days: 175 config changes, 23 produced a downward
//    step, and the sizes split cleanly with nothing between 0.60 and 0.80. A manual
//    +-1 K comfort edit shows up as 0.6 K or less, because lowering one zone's
//    target usually passes the lead to another zone and the step is the gap
//    between the two, not the size of the edit.
//
// 2. A new heat source: a fireplace, or sun through the skylights. The house has
//    gained heat the controller did not command, so the history is just as stale.
//    This one is gradual, not stepwise, so the rise over pid_rise_window_s supplies
//    the step instead.
//    Measured over 21 days: heating alone never moved any zone more than 1.0 K per
//    30 min. The boiler never ran above 60 percent of a 30 min window at a command
//    of 55 or more, so the real heating ceiling is above what was observed and the
//    threshold allows for it. Replaying 25 Oct fired on both the afternoon sun
//    (+2.00) and the fire that evening (+2.60).
var now = Date.now()

var cfg = {}
Object.keys(zones).forEach(function (z) {
    var t = zones[z]
    cfg[z] = (t.state === 'off' ? 'off' : 'heat') + ':' + t.attributes.temperature
})
var prevCfg    = flow.get('pid_cfg')
var prevLeader = flow.get('pid_prev_leader')
flow.set('pid_cfg', cfg)
flow.set('pid_prev_leader', leader)

// Rolling per-zone temperature history, used only for the rise test.
var riseWin = flow.get('pid_rise_window_s') * 1000
var riseK   = flow.get('pid_rise_k')
var hist = flow.get('pid_temp_hist') || {}
var riseZone = null, riseAmt = 0
Object.keys(curs).forEach(function (z) {
    if (z === 'backup') return
    var h = hist[z] || []
    h.push([now, curs[z]])
    while (h.length > 1 && now - h[0][0] > riseWin) h.shift()
    hist[z] = h
    if (now - h[0][0] < riseWin * 0.9) return      // not enough history yet
    var r = curs[z] - h[0][1]
    if (r >= riseK && r > riseAmt) { riseZone = z; riseAmt = r }
})
flow.set('pid_temp_hist', hist)

// Fire once per episode. A rise stays above the threshold for as long as the
// window is wide, so without a latch this would correct on every 15 s cycle. The
// latch clears once the zone has stopped climbing, at half the threshold.
var latch = flow.get('pid_rise_latch') || null
if (latch !== null && latch !== riseZone) {
    var lh = hist[latch] || []
    if (lh.length < 2 || curs[latch] === undefined ||
        curs[latch] - lh[0][1] < riseK / 2) { latch = null; flow.set('pid_rise_latch', null) }
}
var riseEvent = (riseZone !== null && latch !== riseZone)
if (riseEvent) flow.set('pid_rise_latch', riseZone)

var err     = new_setpoint - curs[leader]
var prevErr = flow.get('pid_prev_err')
var prevI   = flow.get('pid_last_integral')
flow.set('pid_prev_err', err)

var step = null, why = ''
if (prevErr !== undefined && prevErr !== null) {
    var s = err - prevErr
    var thr = flow.get('pid_step_thresh')
    // BOTH directions, on the same config-change gate.
    // Down: demand fell for a reason that is not the heating system's doing, so the
    // accumulated history is stale and would command heat into a satisfied house.
    // Up: demand rose, and if the integral is sitting at the suppression clamp the
    // loop must unwind up to pb/2 before it can respond. Measured 17 Nov: drawing_room
    // and nursery are unoccupied, so overnight the only leader is bedroom at its
    // 18.0 night target while sitting 19.2, which pins the integral at +3.00. Raising
    // bedroom to 19.5 at 02:00 then took two hours of unwinding before the command
    // reached a sensible level, and the room needed 5.5 h to recover 1.7 K.
    // Requirement: a cold room gets heat now, not after the integral unwinds.
    // An earlier symmetric version was simulated in November and raised gas sharply,
    // but that one triggered on the error step ALONE and so fired on every leader
    // swap. This fires only when the departing leader's own mode or target changed.
    if (Math.abs(s) >= thr) {
        var leadChanged = (prevCfg !== undefined && prevCfg !== null &&
                           prevLeader !== undefined && prevLeader !== null &&
                           prevCfg[prevLeader] !== undefined &&
                           prevCfg[prevLeader] !== cfg[prevLeader])
        if (leadChanged) {
            step = s
            why = 'config change in ' + prevLeader + ' (' + prevCfg[prevLeader] + ' -> ' +
                  cfg[prevLeader] + '), error step ' + s.toFixed(2) + ' K (' +
                  prevErr.toFixed(2) + ' -> ' + err.toFixed(2) + ')'
        } else if (prevLeader !== leader) {
            node.warn('error step ' + s.toFixed(2) + ' K ignored: lead passed ' +
                      prevLeader + ' -> ' + leader + ' with no config change in ' + prevLeader)
        }
    }
}
if (step === null && riseEvent && err < 0) {
    // Only when the leader is at or above target. A fire in one room must not cut
    // heat to a room that is genuinely cold.
    step = -riseAmt
    why = 'external heat in ' + riseZone + ', +' + riseAmt.toFixed(2) + ' K in ' +
          (riseWin / 60000) + ' min'
}

if (step !== null && prevI !== undefined && prevI !== null) {
    // The internal integral is inverted: a more positive integral lowers the
    // output, so undoing a drop of `step` means subtracting it. The node clamps to
    // +-pb/2 itself, and its anti-windup lock clears on its own as the room drifts
    // (the lock test uses the live error), so no boundary guard is needed here.
    out.integral = prevI - step
    node.warn(why + ', integral ' + prevI.toFixed(2) + ' -> ' + (prevI - step).toFixed(2))
}

node.log('leader: ' + leader + ', PV: ' + out.payload + ', SP: ' + out.setpoint +
         (stuck.length ? ', stuck: ' + stuck.join(',') : ''))
node.status({ fill: stuck.length ? 'yellow' : 'green', shape: 'ring',
    text: leader + ' ' + out.payload + '->' + out.setpoint +
          (stuck.length ? ' stuck:' + stuck.length : '') })
return out;

var raw = msg.payload
// The PID clamps power to 0..1, so raw == 0 is exact and means fully satisfied.
// Measured over 7 days: every minute spent commanding 10-20 C had boiler water
// already hotter than the command, so none of it could produce heat.
//
// The curve is raw^k, not linear. A linear map puts the zero-error point exactly
// halfway between flow_min and the ceiling, so with the floor pinned at 20 the only
// way to lower it was to lower the ceiling too (40 C zero point forces a 60 C max).
// An exponent bends the middle down while keeping both ends, and it also matches the
// plant: radiator output goes roughly as deltaT^1.3, so heat delivered is convex in
// flow temperature and equal steps of PID output now buy closer to equal steps of heat.
// Measured need: over steady hours the house actually receives 27-44 C mean water
// (burner on and off together, CH duty only 6-31%), against 47.5 C commanded at zero
// error under the old linear map. k=1.4 puts the zero-error point at 40.8 C.
// Simulated on the real 14-day trace: median command 39.3 -> 32.7, hours above 55 C
// 24.2 -> 7.2, ceiling unchanged at 75, morning recovery p90 59.2 -> 54.2.
var k   = flow.get('flow_exp')
var out = (raw <= 0) ? flow.get('flow_idle')
                     : flow.get('flow_min') + flow.get('flow_span') * Math.pow(raw, k)
msg.payload = out
node.status({ fill: raw <= 0 ? 'grey' : 'green', shape: 'ring',
    text: raw.toFixed(3) + ' -> ' + out.toFixed(1) + 'C' })
return msg;

//{ "payload": 10.07316516362641, 
//"pv": 19.6, 
//"setpoint": 19.5, 
//"proportional": 0.10000000000000142, 
//"integral": 0.40165963888889067, 
//"derivative": -0.002785256790836854, 
//"smoothed_value": 19.60120696627247, 
//"_msgid": "89356c052bdf15c6" }
flow.set('pid_last_integral', msg.integral)
node.status({fill:"green",shape:"ring",text: JSON.stringify(msg)});
['setpoint',
    'pv',
    'proportional',
    'integral',
    'derivative',
    'payload'].forEach( function(p) {
        var m=
        {'payload':{
            'op':'set',
            'val': RED.util.getMessageProperty(msg,p),
            'labels':
                {"component": p}
            }}
        node.send(m);
        }
    )

// export demand for EVERY zone, not just the leader,
// so per-zone series stay live instead of freezing at their last leadership
var d = msg.demands || {}
Object.keys(d).forEach(function (zone) {
    node.send({ payload: { op: 'set', val: d[zone], labels: { zone: zone } } })
})

var stuck = msg.stuck || []
var zones = flow.get('zones') || []
zones.forEach(function (z) {
    node.send({ payload: { op: 'set', val: stuck.indexOf(z) >= 0 ? 1 : 0,
                           labels: { zone: z, flag: 'sensor_stuck' } } })
})

// is_leader: 1 for the zone feeding the PID, 0 for all the others, written EVERY
// cycle for every configured zone plus backup.
// Grafana used to infer the leader from heating_demand, which breaks twice. A zone
// skipped by off_lead_margin stops appearing in msg.demands, so its series stops
// updating and Prometheus carries the last value for 5 min: on 26 Nov that showed
// drawing_room leading at 03:10 when the flow's own log says bedroom did. And a
// comparison against max() returns EVERY tied series, so exact ties drew two zones
// as leader at once (14 ties in one 13 h window). A flag written every cycle cannot
// go stale, and the flow picks exactly one leader so it cannot tie.
zones.concat(['backup']).forEach(function (z) {
    node.send({ payload: { op: 'set', val: (z === msg.leader) ? 1 : 0,
                           labels: { zone: z, flag: 'is_leader' } } })
})

var res={
    "op": "inc",
        "val": 1,
            "labels": {
        "node_id": msg.error.source.id,
        "node_name": msg.error.source.name,
        "node_type": msg.error.source.type,
        "message": msg.error.message
    }
}
msg.payload=res
node.status({fill:"red",shape:"ring",text:JSON.stringify(msg)});
return msg;

// Publishes heating_entity_dependency{entity,role,zone} = 1 for every HA entity this
// tab depends on. Prometheus joins it with homeassistant_entity_available to alert
// on unavailable dependencies, because HA labels are not exported by its integration.
// Zone thermostats and TRVs are derived from 'zones', so a new zone is covered.
// Source sensors must be listed by hand: a generic_thermostat stays available when its
// target_sensor dies (only current_temperature goes null), and target_sensor is not
// in the entity attributes. Keep in sync with /config/thermostats.yaml.
var zone_sensors = {
    workshop:   ['sensor.workshop_temperature'],
    livingroom: ['sensor.livingroom_temperature', 'sensor.living_room_sonoff_temp_temperature'],
    bedroom:    ['sensor.bedroom_sensor_temperature'],
    nursery:    ['sensor.nursery_temperature'],
    drawing_room:  ['sensor.drawing_room_temperature']
}
var deps = [
    { entity: 'climate.boiler_direct',             role: 'boiler',         zone: 'none' },
    { entity: 'input_boolean.boileroverrideenable', role: 'control_switch', zone: 'none' },
    { entity: 'input_boolean.trv_control_enabled',  role: 'control_switch', zone: 'none' }
]
var zones = flow.get('zones') || []
zones.forEach(function (z) {
    deps.push({ entity: 'climate.' + z + '_thermostat', role: 'zone_thermostat', zone: z })
    deps.push({ entity: 'climate.trv_' + z,             role: 'trv',             zone: z })
    if (!zone_sensors[z]) node.error('no source sensor listed for zone ' + z, msg)
    ;(zone_sensors[z] || []).forEach(function (s) {
        deps.push({ entity: s, role: 'zone_sensor', zone: z })
    })
})
deps.forEach(function (d) {
    node.send({ payload: { op: 'set', val: 1, labels: d } })
})
node.status({ fill: 'green', shape: 'ring', text: deps.length + ' entities' })
return null;

// Fires on the input_boolean transition to off, NOT on the polled gate: that gate
// emits every 15 s cycle while disabled and these are sleepy battery devices.
// Opening fully is the point. Turning TRV control off means the valves are no longer
// managed, and a valve left at its last command is still being managed, by a stale
// one. Three cases want exactly this: manual maintenance (flushing, degassing), the
// pump's periodic circulation while heating is off, and handing the house to the
// hardware thermostat. Boiler control already surrenders this way (Set 0 to
// surrender boiler control); TRV control had no such path and left valves wherever
// they happened to be, which for an off zone is 16, i.e. shut.
var zones = flow.get('zones') || []
var open  = flow.get('trv_max_setpoint')
// Drop the PI state so re-enabling starts clean instead of resuming with integrals
// accumulated before the manual period.
flow.set('trv_state', {})
var out = zones.map(function (z) {
    var trv = 'climate.trv_' + z
    return { topic: trv, data: { entity_id: trv, temperature: open } }
})
node.warn('TRV control off: opening ' + zones.length + ' valves to ' + open)
node.status({ fill: 'blue', shape: 'dot', text: 'opened ' + zones.length + ' to ' + open })
return [out];
